import math

def gcd_three(a, b, c):
    return math.gcd(a, math.gcd(b, c))

def solve():
    good_numbers = set()
    MAX_VAL = 30

    # Iterate through all triplets (a, b, c) such that 1 <= a <= b <= c <= 30
    for a in range(1, MAX_VAL + 1):
        for b in range(a, MAX_VAL + 1):
            for c in range(b, MAX_VAL + 1):

                # Check Condition 1: GCD(a, b, c) = 1
                if gcd_three(a, b, c) != 1:
                    continue

                # Check Condition 2: Divisibility constraints for U={a, b, c} with a <= b <= c
                # 1. Pair {a, b}: c | ab
                c_divides_ab = (a * b) % c == 0

                # 2. Pair {a, c}: b | ac
                b_divides_ac = (a * c) % b == 0

                # 3. Pair {b, c}: a | bc
                a_divides_bc = (b * c) % a == 0

                if c_divides_ab and b_divides_ac and a_divides_bc:
                    m = a * b * c
                    good_numbers.add(m)

    sorted_good_numbers = sorted(list(good_numbers))

    print(f"Total number of unique good numbers found: {len(sorted_good_numbers)}")

    if len(sorted_good_numbers) >= 20:
        print(f"The 20th smallest good number is: {sorted_good_numbers[19]}")
    else:
        print("Not enough good numbers found to determine the 20th smallest.")

